window.AUTH=window.AUTH||{};window.AUTH["25-466"]={"d":"25-466","id":"2025/25-466","n":"Sripetch v. SEC","briefs":[{"k":"petitioner","label":"Brief of petitioner Ongkaruck Sripetch","date":"2026-02-23","url":"https://www.supremecourt.gov/DocketPDF/25/25-466/397105/20260223230227953_25-466%20ts.pdf","side":"pet","n":55},{"k":"respondent","label":"Brief of respondent","date":"2026-03-25","url":"https://www.supremecourt.gov/DocketPDF/25/25-466/403099/20260327170542544_25-466_Sripetch_bs.pdf","side":"res","n":79},{"k":"reply","label":"Reply of petitioner Ongkaruck Sripetch","date":"2026-04-10","url":"https://www.supremecourt.gov/DocketPDF/25/25-466/404142/20260410135751288_25-466%20rb.pdf","side":"pet","n":31}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/608us2r44_j42l.pdf","tr":true,"items":[{"t":"case","label":"Am. Univ. v. Forbes","cite":"183 A. 860","y":1936,"court":"N.H.","url":"https://www.courtlistener.com/c/A./183/860/","by":{"0":"30","2":"18"}},{"t":"case","label":"AMG Cap. Mgmt., LLC v. Fed. Trade Comm’n","cite":"593 U.S. 67","y":2021,"url":"https://supreme.justia.com/cases/federal/us/593/67/","sc":1,"by":{"0":"30"}},{"t":"case","label":"Armstrong v. Exceptional Child Ctr., Inc.","cite":"575 U.S. 320","y":2015,"id":"2014/14-15","sc":1,"sum":"A case that determines whether or not a private right of action exists under the Medicaid Act.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Bragdon v. Abbott","cite":"524 U.S. 624","y":1998,"id":"1997/97-156","sc":1,"sum":"In a 5-to-4 opinion, the Court held that although the ADA does not force care-givers to treat an \"individual [who] poses a direct threat to the health or safety of others,\" it also prohibits discrimination against any individual \"on the basis of disability in the enjoyment of the services of any place of public accommodation by any person who operates [such] a place.\" The Court then reasoned that since HIV \"substantially limits\" major life activities, such as reproduction, the infection is a \"disability\" that entitles its victims to ADA protections.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Bright v. Boyd","cite":"4 F. Cas. 127","y":1841,"court":"C.C.D. Me.","url":"https://www.courtlistener.com/c/F.%20Cas./4/127/","by":{"0":"29"}},{"t":"case","label":"Dura Pharmaceuticals, Inc. v. Broudo","cite":"544 U.S. 336","y":2005,"id":"2004/03-932","sc":1,"sum":"The Court held that an inflated purchase price did not by itself prove \"loss causation.\" At most, an inflated purchase price suggested that misrepresentation \"touched upon\" a later economic loss, but did not necessarily cause it.","sumSrc":"Oyez","by":{"0":"9, 26","1":"15, 22"}},{"t":"case","label":"Gabelli v. SEC","cite":"568 U.S. 442","y":2013,"id":"2012/11-1274","sc":1,"sum":"The Court held that a five-year statute of limitations period begins at the time the violation is committed.","sumSrc":"Oyez","by":{"0":"4, 16"}},{"t":"case","label":"Great-W. Life & Annuity Ins. Co. v. Knudson","cite":"534 U.S. 204","y":2002,"id":"2001/99-1786","sc":1,"op":4,"sum":"The Court held that because Great-West is seeking legal relief - the imposition of personal liability on Knudson for a contractual obligation to pay money - ERISA does not authorize this action.","sumSrc":"Oyez","by":{"0":"31, 32","2":"4, 17"}},{"t":"case","label":"Hamilton-Brown Shoe Co. v. Wolf Bros. & Co.","cite":"240 U.S. 251","y":1916,"id":"scdb/1915-097","sc":1,"sum":"The words “The American Girl” as applied to women’s shoes is not a geographical or descriptive term signifying that the articles are manufactured in America, or intended to be.sold therein; nor does it indicate qualities or characteristics of the article.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"31, 35","2":"14, 17"}},{"t":"case","label":"Johnson v. SEC","cite":"87 F.3d 484","y":1996,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/87/484/","by":{"0":"4"}},{"t":"case","label":"Kansas v. Nebraska","cite":"574 U.S. 445","y":2015,"id":"2014/126-orig","sc":1,"ar":2,"sum":"The Court ruled that Nebraska violated a compact apportioning the water resources of the Republican River among Kansas, Nebraska and Colorado.","sumSrc":"Oyez","by":{"0":"34","1":"15"}},{"t":"case","label":"Kilbourn v. Sunderland","cite":"130 U.S. 505","y":1889,"id":"scdb/1888-195","sc":1,"sum":"Where it is competent for a court of equity to grant the relief asked for, and it has jurisdiction of the subject matter, the objection that the - complainant has an adequate remedy at. law should be taken at the earliest opportunity, and before the defendants enter upon a full defence. Reynes v. Dumont, 130 U. S. 354, followed.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"32","2":"14"}},{"t":"case","label":"Kokesh v. SEC","cite":"581 U.S. 455","y":2017,"id":"2016/16-529","sc":1,"op":4,"ar":3,"sum":"The Court held that Securities and Exchange Commission (SEC) disgorgement functions as a penalty, and therefore is subject to the five-year statute of limitations.Commission seeking “disgorgement,” or payment, of illegally obtained funds.","sumSrc":"Oyez","by":{"0":"3-4, 6, 15-18, 23-26","1":"3, 4, 14, 15, 17, 18, 23","2":"1, 2, 5"}},{"t":"case","label":"Leman v. Krentler-Arnold Hinge Last Co.","cite":"284 U.S. 448","y":1932,"id":"scdb/1931-129","sc":1,"op":1,"ar":1,"by":{"0":"32","1":"30","2":"5, 15, 17"}},{"t":"case","label":"Liu v. SEC","cite":"591 U.S. 71","y":2020,"url":"https://supreme.justia.com/cases/federal/us/591/71/","sc":1,"op":16,"sum":"Describing equitable accounting in patent cases, where a plaintiff may recover “profits that the defendants have made by the use of his invention” (quotation omitted).","sumSrc":"brief:0","by":{"0":"21","1":"2, 4, 5, 9, 10, 13, 14, 17, 24, 26-31, 33, 34","2":"1-10, 12-15, 19"}},{"t":"case","label":"Marshall v. Vicksburg","cite":"82 U.S. 146","y":1823,"id":"scdb/1872-071","sc":1,"op":2,"by":{"0":"15"}},{"t":"case","label":"Moses v. Macferlan","cite":"97 Eng. Rep. 676","y":1760,"court":"K.B.","url":"https://www.courtlistener.com/c/Eng.%20Rep./97/676/","op":1,"by":{"0":"30"}},{"t":"case","label":"Porter v. Warner Holding Co.","cite":"328 U.S. 395","y":1946,"id":"scdb/1945-032","sc":1,"sum":"1. In an.enforcement proceeding under § 205 (a) of the Emergency Price Control Act of 1942, a Federal District Court has power to order restitution of rents collected by a landlord in excess of maximums established by regulations issued under the Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 30","2":"6, 14, 15, 18"}},{"t":"case","label":"Root v. Lake Shore & M.S. Ry. Co.","cite":"105 U.S. 189","y":1881,"id":"scdb/1881-134","sc":1,"by":{"0":"31","1":"14"}},{"t":"case","label":"Saad v. SEC","cite":"873 F.3d 297","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/873/297/","by":{"0":"17"}},{"t":"case","label":"SEC v. Govil","cite":"86 F.4th 89","y":2023,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/86/89/","op":1,"by":{"0":"17, 26, 32, 36","1":"16, 23, 29","2":"1"}},{"t":"case","label":"SEC v. Jarkesy","cite":"603 U.S. 109","y":2024,"url":"https://supreme.justia.com/cases/federal/us/603/109/","sc":1,"op":3,"ar":12,"sum":"Holding that, when the SEC seeks penalties, the Seventh Amendment entitles the defendant to a jury trial.","sumSrc":"opinion","by":{"0":"16, 17, 19, 20, 22","2":"1, 2, 5, 7"}},{"t":"case","label":"SEC v. Quan","cite":"817 F.3d 583","y":2016,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/817/583/","by":{"0":"4"}},{"t":"case","label":"SEC v. Rind","cite":"991 F.2d 1486","y":1993,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/991/1486/","by":{"0":"4","1":"24, 25"}},{"t":"case","label":"SEC v. Texas Gulf Sulphur Co.","cite":"312 F. Supp. 77","y":1970,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./312/77/","op":1,"by":{"0":"3"}},{"t":"case","label":"SEC v. Texas Gulf Sulphur Co.","cite":"446 F.2d 1301","y":1971,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/446/1301/","op":2,"by":{"0":"3","1":"4"}},{"t":"case","label":"Stone v. White","cite":"301 U.S. 532","y":1937,"id":"scdb/1936-129","sc":1,"sum":"1. A statutory action for a refund of taxes erroneously collected is in the nature of a common law action for money had and received and like it is governed by equitable principles.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30, 31"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"587 U.S. 554","y":2019,"id":"2018/18-489","sc":1,"sum":"A creditor may be held in civil contempt for violating a bankruptcy court’s discharge order if there is no fair ground of doubt as to whether the order barred the creditor’s conduct.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"22"}},{"t":"case","label":"Tilghman v. Proctor","cite":"125 U.S. 136","y":1888,"id":"scdb/1887-171","sc":1,"sum":"One having an interest in all fees and other sums to be recovered under a patent, but not shown to have'any interest, legal or equitable, in the patent itself, need not be made a party to a bill in equity for its infringement.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"17, 31, 32","2":"2, 17"}},{"t":"case","label":"Tull v. United States","cite":"481 U.S. 412","y":1987,"id":"1986/85-1259","sc":1,"op":1,"sum":"The Clean Water Act (Act) authorizes injunctive relief against violators (33 U. S. C. § 1319(b)) and subjects them to a civil penalty not to exceed $10,000 per day (§ 1319(d)). After denying petitioner's timely demand for a jury trial in the Government's suit for relief under §§ 1319(b) and 1319(d), the District Court imposed civil penalties and granted injunctive relief against petitioner. The Court of Appeals …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 30","2":"2, 14"}},{"t":"law","label":"Pub. L. No. 107-204","url":"https://www.govinfo.gov/link/plaw/107/public/204","by":{"0":"4","1":"5"}},{"t":"law","label":"Pub. L. No. 101-429","url":"https://www.govinfo.gov/link/statute/104/931","by":{"0":"3"}},{"t":"law","label":"Pub. L. No. 116-283","url":"https://www.govinfo.gov/link/plaw/116/public/283","by":{"0":"6","1":"6, 36"}},{"t":"usc","label":"15 U.S.C. § 77e","url":"https://www.law.cornell.edu/uscode/text/15/77e","subs":["(a)(1)"],"stext":{"head":"§77e. Prohibitions relating to interstate commerce and the mails","paras":[[0,"(a) Sale or delivery after sale of unregistered securities"],[0,"Unless a registration statement is in effect as to a security, it shall be unlawful for any person, directly or indirectly—"],[1,"(1) to make use of any means or instruments of transportation or communication in interstate commerce or of the mails to sell such security through the use or medium of any prospectus or otherwise; or"],[1,"(2) to carry or cause to be carried through the mails or in interstate commerce, by any means or instruments of transportation, any such security for the purpose of sale or for delivery after sale."],[0,"(b) Necessity of prospectus meeting requirements of section 77j of this title"],[0,"It shall be unlawful for any person, directly or indirectly—"],[1,"(1) to make use of any means or instruments of transportation or communication in interstate commerce or of the mails to carry or transmit any prospectus relating to any security with respect to which a registration statement has been filed under this subchapter, unless such prospectus meets the requirements of section 77j of this title; or"],[1,"(2) to carry or cause to be carried through the mails or in interstate commerce any such security for the purpose of sale or for delivery after sale, unless accompanied or preceded by a prospectus that meets the requirements of subsection (a) of section 77j of this title."],[0,"(c) Necessity of filing registration statement"],[0,"It shall be unlawful for any person, directly or indirectly, to make use of any means or instruments of transportation or communication in interstate commerce or of the mails to offer to sell or offer to buy through the use or medium of any prospectus or otherwise any security, unless a registration statement has been filed as to such security, or while the registration statement is the subject of a refusal order or stop order or (prior to the effective date of the registration statement) any public proceeding or examination under section 77h of this title."],[0,"(d) Limitation"],[0,"Notwithstanding any other provision of this section, an emerging growth company or any person authorized to act on behalf of an emerging growth company may engage in oral or written communications with potential investors that are qualified institutional buyers or institutions that are accredited investors, as such terms are respectively defined in section 230.144A and section 230.501(a) of title 17, Code of Federal Regulations, or any successor thereto, to determine whether such investors might have an interest in a contemplated securities offering, either prior to or following the date of filing of a registration statement with respect to such securities with the Commission, subject to the requirement of subsection (b)(2)."],[0,"(e) Security-based swaps"],[0,"Notwithstanding the provisions of section 77c or 77d of this title, unless a registration statement meeting the requirements of section 77j(a) of this title is in effect as to a security-based swap, it shall be unlawful for any person, directly or indirectly, to make use of any means or instruments of transportation or communication in interstate commerce or of the mails to offer to sell, offer to buy or purchase or sell a security-based swap to any person who is not an eligible contract participant as defined in section 1a(18) of title 7."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77e?type=usc&year=mostrecent&link-type=html"},"head":"§77e. Prohibitions relating to interstate commerce and the mails","tname":"Commerce and Trade","by":{"0":"8","1":"7"}},{"t":"usc","label":"15 U.S.C. § 77t","url":"https://www.law.cornell.edu/uscode/text/15/77t","subs":["(d)"],"by":{"0":"3"}},{"t":"usc","label":"15 U.S.C. § 77x","url":"https://www.law.cornell.edu/uscode/text/15/77x","stext":{"head":"§77x. Penalties","paras":[[0,"Any person who willfully violates any of the provisions of this subchapter, or the rules and regulations promulgated by the Commission under authority thereof, or any person who willfully, in a registration statement filed under this subchapter, makes any untrue statement of a material fact or omits to state any material fact required to be stated therein or necessary to make the statements therein not misleading, shall upon conviction be fined not more than $10,000 or imprisoned not more than five years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77x?type=usc&year=mostrecent&link-type=html"},"head":"§77x. Penalties","tname":"Commerce and Trade","by":{"0":"8","1":"7"}},{"t":"usc","label":"15 U.S.C. § 78l","url":"https://www.law.cornell.edu/uscode/text/15/78l","subs":["(j)"],"by":{"0":"7"}},{"t":"usc","label":"15 U.S.C. § 78o","url":"https://www.law.cornell.edu/uscode/text/15/78o","subs":["(b)(4)"],"by":{"0":"7"}},{"t":"usc","label":"15 U.S.C. § 78u","url":"https://www.law.cornell.edu/uscode/text/15/78u","subs":["(d)","(d)(1)","(d)(2)","(d)(3)","(d)(3)(A)(i)","(d)(3)(A)(ii)","(d)(3)(B)","(d)(5)","(d)(6)","(d)(7)","(d)(8)(A)","(d)(8)(B)","(d)(3)(A)","(d)(3)(B)(iii)","(d)(8)","(d)(8)(A)(i)","(d)(8)(A)(ii)","(d)(9)","(g)","(h)","(h)(2)"],"stext":{"head":"§78u. Investigations and actions","paras":[[0,"(a) Authority and discretion of Commission to investigate violations"],[0,"(1) The Commission may, in its discretion, make such investigations as it deems necessary to determine whether any person has violated, is violating, or is about to violate any provision of this chapter, the rules or regulations thereunder, the rules of a national securities exchange or registered securities association of which such person is a member or a person associated, or, as to any act or practice, or omission to act, while associated with a member, formerly associated with a member, the rules of a registered clearing agency in which such person is a participant, or, as to any act or practice, or omission to act, while a participant, was a participant, the rules of the Public Company Accounting Oversight Board, of which such person is a registered public accounting firm, a person associated with such a firm, or, as to any act, practice, or omission to act, while associated with such firm, a person formerly associated with such a firm, or the rules of the Municipal Securities Rulemaking Board, and may require or permit any person to file with it a statement in writing, under oath or otherwise as the Commission shall determine, as to all the facts and circumstances concerning the matter to be investigated. The Commission is authorized in its discretion, to publish information concerning any such violations, and to investigate any facts, conditions, practices, or matters which it may deem necessary or proper to aid in the enforcement of such provisions, in the prescribing of rules and regulations under this chapter, or in securing information to serve as a basis for recommending further legislation concerning the matters to which this chapter relates."],[0,"(2) On request from a foreign securities authority, the Commission may provide assistance in accordance with this paragraph if the requesting authority states that the requesting authority is conducting an investigation which it deems necessary to determine whether any person has violated, is violating, or is about to violate any laws or rules relating to securities matters that the requesting authority administers or enforces. The Commission may, in its discretion, conduct such investigation as the Commission deems necessary to collect information and evidence pertinent to the request for assistance. Such assistance may be provided without regard to whether the facts stated in the request would also constitute a violation of the laws of the United States. In deciding whether to provide such assistance, the Commission shall consider whether (A) the requesting authority has agreed to provide reciprocal assistance in securities matters to the Commission; and (B) compliance with the request would prejudice the public interest of the United States."],[0,"(b) Attendance of witnesses; production of records"],[0,"For the purpose of any such investigation, or any other proceeding under this chapter, any member of the Commission or any officer designated by it is empowered to administer oaths and affirmations, subpena witnesses, compel their attendance, take evidence, and require the production of any books, papers, correspondence, memoranda, or other records which the Commission deems relevant or material to the inquiry. Such attendance of witnesses and the production of any such records may be required from any place in the United States or any State at any designated place of hearing."],[0,"(c) Judicial enforcement of investigative power of Commission; refusal to obey subpena; criminal sanctions"],[0,"In case of contumacy by, or refusal to obey a subpena issued to, any person, the Commission may invoke the aid of any court of the United States within the jurisdiction of which such investigation or proceeding is carried on, or where such person resides or carries on business, in requiring the attendance and testimony of witnesses and the production of books, papers, correspondence, memoranda, and other records. And such court may issue an order requiring such person to appear before the Commission or member or officer designated by the Commission, there to produce records, if so ordered, or to give testimony touching the matter under investigation or in question; and any failure to obey such order of the court may be punished by such court as a contempt thereof. All process in any such case may be served in the judicial district whereof such person is an inhabitant or wherever he may be found. Any person who shall, without just cause, fail or refuse to attend and testify or to answer any lawful inquiry or to produce books, papers, correspondence, memoranda, and other records, if in his power so to do, in obedience to the subpena of the Commission, shall be guilty of a misdemeanor and, upon conviction, shall be subject to a fine of not more than $1,000 or to imprisonment for a term of not more than one year, or both."],[0,"(d) Injunction proceedings; authority of court to prohibit persons from serving as officers and directors; money penalties in civil actions; disgorgement"],[0,"(1) Whenever it shall appear to the Commission that any person is engaged or is about to engage in acts or practices constituting a violation of any provision of this chapter, the rules or regulations thereunder, the rules of a national securities exchange or registered securities association of which such person is a member or a person associated with a member, the rules of a registered clearing agency in which such person is a participant, the rules of the Public Company Accounting Oversight Board, of which such person is a registered public accounting firm or a person associated with such a firm, or the rules of the Municipal Securities Rulemaking Board, it may in its discretion bring an action in the proper district court of the United States, the United States District Court for the District of Columbia, or the United States courts of any territory or other place subject to the jurisdiction of the United States, to enjoin such acts or practices, and upon a proper showing a permanent or temporary injunction or restraining order shall be granted without bond. The Commission may transmit such evidence as may be available concerning such acts or practices as may constitute a violation of any provision of this chapter or the rules or regulations thereunder to the Attorney General, who may, in his discretion, institute the necessary criminal proceedings under this chapter."],[0,"(2) Authority of Court To Prohibit Persons From Serving as Officers and Directors.—In any proceeding under paragraph (1) of this subsection, the court may prohibit, conditionally or unconditionally, and permanently or for such period of time as it shall determine, any person who violated section 78j(b) of this title or the rules or regulations thereunder from acting as an officer or director of any issuer that has a class of securities registered pursuant to section 78l of this title or that is required to file reports pursuant to section 78o(d) of this title if the person's conduct demonstrates unfitness to serve as an officer or director of any such issuer."],[0,"(3) Civil money penalties and authority to seek disgorgement.—"],[1,"(A) Authority of commission.—Whenever it shall appear to the Commission that any person has violated any provision of this chapter, the rules or regulations thereunder, or a cease-and-desist order entered by the Commission pursuant to section 78u–3 of this title, other than by committing a violation subject to a penalty pursuant to section 78u–1 of this title, the Commission may bring an action in a United States district court to seek, and the court shall have jurisdiction to—"],[2,"(i) impose, upon a proper showing, a civil penalty to be paid by the person who committed such violation; and"],[2,"(ii) require disgorgement under paragraph (7) of any unjust enrichment by the person who received such unjust enrichment as a result of such violation."],[1,"(B) Amount of penalty.—"],[2,"(i) First tier.—The amount of a civil penalty imposed under subparagraph (A)(i) shall be determined by the court in light of the facts and circumstances. For each violation, the amount of the penalty shall not exceed the greater of (I) $5,000 for a natural person or $50,000 for any other person, or (II) the gross amount of pecuniary gain to such defendant as a result of the violation."],[2,"(ii) Second tier.—Notwithstanding clause (i), the amount of a civil penalty imposed under subparagraph (A)(i) for each such violation shall not exceed the greater of (I) $50,000 for a natural person or $250,000 for any other person, or (II) the gross amount of pecuniary gain to such defendant as a result of the violation, if the violation described in subparagraph (A) involved fraud, deceit, manipulation, or deliberate or reckless disregard of a regulatory requirement."],[2,"(iii) Third tier.—Notwithstanding clauses (i) and (ii), the amount of a civil penalty imposed under subparagraph (A)(i) for each violation described in that subparagraph shall not exceed the greater of (I) $100,000 for a natural person or $500,000 for any other person, or (II) the gross amount of pecuniary gain to such defendant as a result of the violation, if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78u?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":1,"head":"§78u. Investigations and actions","tname":"Commerce and Trade","by":{"0":"7, 7, 7, 3, 7, 24, 26, 7, 7, 24, 7, 7, 7, 6, 25, 6, 25, 6","1":"22, 23, 22, 23, 22, 23, 22, 23, 22, 23, 22, 23, 22, 23, 22, 23, 22, 23, 22, 23, 22, 23, 22, 23, 22, 23, 22, 23, 22, 23, 22, 23, 22, 23, 22, 23, 22, 23, 22, 23","2":"1, 4, 7, 9, 10, 12, 19, 7, 3, 4, 7, 9, 10, 12, 19, 10, 10"}},{"t":"usc","label":"15 U.S.C. § 78u-4","url":"https://www.law.cornell.edu/uscode/text/15/78u-4","subs":["(b)(4)"],"stext":{"head":"§78u–4. Private securities litigation","paras":[[0,"(a) Private class actions"],[0,"(1) In general"],[1,"The provisions of this subsection shall apply in each private action arising under this chapter that is brought as a plaintiff class action pursuant to the Federal Rules of Civil Procedure."],[0,"(2) Certification filed with complaint"],[0,"(A) In general"],[2,"Each plaintiff seeking to serve as a representative party on behalf of a class shall provide a sworn certification, which shall be personally signed by such plaintiff and filed with the complaint, that—"],[3,"(i) states that the plaintiff has reviewed the complaint and authorized its filing;"],[3,"(ii) states that the plaintiff did not purchase the security that is the subject of the complaint at the direction of plaintiff's counsel or in order to participate in any private action arising under this chapter;"],[3,"(iii) states that the plaintiff is willing to serve as a representative party on behalf of a class, including providing testimony at deposition and trial, if necessary;"],[3,"(iv) sets forth all of the transactions of the plaintiff in the security that is the subject of the complaint during the class period specified in the complaint;"],[3,"(v) identifies any other action under this chapter, filed during the 3-year period preceding the date on which the certification is signed by the plaintiff, in which the plaintiff has sought to serve as a representative party on behalf of a class; and"],[3,"(vi) states that the plaintiff will not accept any payment for serving as a representative party on behalf of a class beyond the plaintiff's pro rata share of any recovery, except as ordered or approved by the court in accordance with paragraph (4)."],[0,"(B) Nonwaiver of attorney-client privilege"],[2,"The certification filed pursuant to subparagraph (A) shall not be construed to be a waiver of the attorney-client privilege."],[0,"(3) Appointment of lead plaintiff"],[0,"(A) Early notice to class members"],[0,"(i) In general"],[3,"Not later than 20 days after the date on which the complaint is filed, the plaintiff or plaintiffs shall cause to be published, in a widely circulated national business-oriented publication or wire service, a notice advising members of the purported plaintiff class—"],[4,"(I) of the pendency of the action, the claims asserted therein, and the purported class period; and"],[4,"(II) that, not later than 60 days after the date on which the notice is published, any member of the purported class may move the court to serve as lead plaintiff of the purported class."],[0,"(ii) Multiple actions"],[3,"If more than one action on behalf of a class asserting substantially the same claim or claims arising under this chapter is filed, only the plaintiff or plaintiffs in the first filed action shall be required to cause notice to be published in accordance with clause (i)."],[0,"(iii) Additional notices may be required under Federal rules"],[3,"Notice required under clause (i) shall be in addition to any notice required pursuant to the Federal Rules of Civil Procedure."],[0,"(B) Appointment of lead plaintiff"],[0,"(i) In general"],[3,"Not later than 90 days after the date on which a notice is published under subparagraph (A)(i), the court shall consider any motion made by a purported class member in response to the notice, including any motion by a class member who is not individually named as a plaintiff in the complaint or complaints, and shall appoint as lead plaintiff the member or members of the purported plaintiff class that the court determines to be most capable of adequately representing the interests of class members (hereafter in this paragraph referred to as the \"most adequate plaintiff\") in accordance with this subparagraph."],[0,"(ii) Consolidated actions"],[3,"If more than one action on behalf of a class asserting substantially the same claim or claims arising under this chapter has been filed, and any party has sought to consolidate those actions for pretrial purposes or for trial, the court shall not make the determination required by clause (i) until after the decision on the motion to consolidate is rendered. As soon as practicable after such decision is rendered, the court shall appoint the most adequate plaintiff as lead plaintiff for the consolidated actions in accordance with this paragraph."],[0,"(iii) Rebuttable presumption"],[0,"(I) In general"],[4,"Subject to subclause (II), for purposes of clause (i), the court shall adopt a presumption that the most adequate plaintiff in any private action arising under this chapter is the person or group of persons that—"],[5,"(aa) has either filed the complaint or made a motion in response to a notice under subparagraph (A)(i);"],[5,"(bb) in the determination of the court, has the largest financial interest in the relief sought by the class; and"],[5,"(cc) otherwise satisfies the requirements of Rule 23 of the Federal Rules of Civil Procedure."],[0,"(II) Rebuttal evidence"],[4,"The presumption described in subclause (I) may be rebutted only upon proof by a member of the purported plaintiff class that the presumptively most adequate plaintiff—"],[5,"(aa) will not fairly and adequately protect the interests of the class; or"],[5,"(bb) is subject to unique defenses that render such plaintiff incapable of adequately representing the class."],[0,"(iv) Discovery"],[3,"For purposes of this subparagraph, discovery relating to whether a member or members of the purported plaintiff class is the most adequate plaintiff may be conducted by a plaintiff only if the plaintiff first demonstrates a reasonable basis for a finding that the presumptively most adequate plaintiff is incapable of adequately representing the class."],[0,"(v) Selection of lead counsel"],[3,"The most adequate plaintiff shall, subject to the approval of the court, select and retain counsel to represent the class."],[0,"(vi) Restrictions on professional plaintiffs"],[3,"Except as the court may otherwise permit, consistent with the purposes of this section, a person may be a lead plaintiff, or an officer, director, or fiduciary of a lead plaintiff, in no more than 5 securities class actions brought as plaintiff class actions pursuant to the Federal Rules of Civil Procedure during any 3-year period."],[0,"(4) Recovery by plaintiffs"],[1,"The share of any final judgment or of any settlement that is awarded to a representative party serving on behalf of a class shall be equal, on a per share basis, to the portion of the final judgment or settlement awarded to all other members of the class. Nothing in this paragraph shall be construed to limit the award of reasonable costs and expenses (including lost wages) directly relating to the representation of the class to any representative party serving on behalf of a class."],[0,"(5) Restrictions on settlements under seal"],[1,"The terms and provisions of any settlement agreement of a class action shall not be filed under seal, except that on motion of any party to the settlement, the court may order filing under seal for those portions of a settlement agreement as to which good cause is shown for such filing under seal. For purposes of this paragraph, good cause shall exist only if publication of a term or provision of a settlement agreement would cause direct and substantial harm to any party."],[0,"(6) Restrictions on payment of attorneys' fees and expenses"],[1,"Total attorneys' fees and expenses awarded by the court to counsel for the plaintiff class shall not exceed a reasonable percentage of the amount of any damages and prejudgment interest actually paid to the class."],[0,"(7) Disclosure of settlement terms to class members"],[1,"Any proposed or final settlement agreement that is published or otherwise disseminated to the class shall include each of the following statements, along with a cover page summarizing the information contained in such statements:"],[0,"(A) Statement of plaintiff recovery"],[2,"The amount of the settlement proposed to be distributed to the parties to the action, determined in the aggregate and on an average per share basis."],[0,"(B) Statement of potential outcome of case"],[0,"(i) Agreement on amount of damages"],[3,"If the settling parties agree on the average amount of damages per share that would be recoverable if the plaintiff prevailed on each claim alleged under this chapter, a statement concerning the average amount of such potential damages per share."],[0,"(ii) Disagreement on amount of damages"],[3,"If the parties do not agree on the average amount of damages per share that would be recoverable if the plaintiff prevailed on each claim alleged under this chapter, a statement from each settling party concerning the issue or issues on which the parties disagree."],[0,"(iii) Inadmissibility for certain purposes"],[3,"A statement made in accordance with clause (i) or (ii) concerning the amount of damages shall not be admissible in any Federal or State judicial action or administrative proceeding, other than an action or proceeding arising out of such statement."],[0,"(C) Statement of attorneys' fees or costs sought"],[2,"If any of the settling parties or their counsel intend to apply to the court for an award of attorneys' fees or costs from any fund established as part of the settlement, a statement indicating which parties or counsel intend to make such an application, the amount of fees and costs that will be sought (including the amount of such fees and costs determined on an average per share basis), and a brief explanation supporting the fees and costs sought. Such information shall be clearly summarized on the cover page of any notice to a party of any proposed or final settlement agreement."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78u-4?type=usc&year=mostrecent&link-type=html"},"head":"§78u–4. Private securities litigation","tname":"Commerce and Trade","by":{"0":"26","1":"22, 23","2":"6"}},{"t":"usc","label":"15 U.S.C. § 80a-41","url":"https://www.law.cornell.edu/uscode/text/15/80a-41","subs":["(e)"],"by":{"0":"3"}},{"t":"usc","label":"15 U.S.C. § 80b-9","url":"https://www.law.cornell.edu/uscode/text/15/80b-9","subs":["(e)"],"by":{"0":"3"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 2462","url":"https://www.law.cornell.edu/uscode/text/28/2462","stext":{"head":"§2462. Time for commencing proceedings","paras":[[0,"Except as otherwise provided by Act of Congress, an action, suit or proceeding for the enforcement of any civil fine, penalty, or forfeiture, pecuniary or otherwise, shall not be entertained unless commenced within five years from the date when the claim first accrued if, within the same period, the offender or the property is found within the United States in order that proper service may be made thereon."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2462?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§2462. Time for commencing proceedings","tname":"Judiciary and Judicial Procedure","by":{"0":"4, 21, 24, 25","1":"4, 37"}},{"t":"case","label":"Blue Chip Stamps v. Manor Drug Stores","cite":"421 U.S. 723","y":1975,"id":"1974/74-124","sc":1,"sum":"A private damages action under Rule 10b-5 is confined to actual purchasers or sellers of securities and the Birnbaum rule bars respondent from maintaining this suit.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"CIGNA Corp. v. Amara","cite":"563 U.S. 421","y":2011,"id":"2010/09-804","sc":1,"sum":"The Court held that the U.S. District Court for the District of Connecticut did not have the authority to reform CIGNA's pension plan.","sumSrc":"Oyez","by":{"1":"19","2":"16"}},{"t":"case","label":"Collins v. Yellen","cite":"594 U.S. 220","y":2021,"id":"2020/19-422","sc":1,"sum":"Because the Federal Housing Finance Agency (FHFA) did not exceed its authority under the Housing and Economic Recovery Act of 2008 as a conservator of Fannie Mae and Freddie Mac, the anti-injunction provisions of the Recovery Act bar the statutory claim brought by shareholders of those entities; the Recovery Act’s structure, which restricts the President’s power to remove the FHFA Director, violates the separation of powers.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"21"}},{"t":"case","label":"Commissioner v. Zuch","cite":"605 U.S. 422","y":2025,"id":"2024/24-416","sc":1,"sum":"The United States Tax Court lacks jurisdiction under 26 U. S. C. §6330 to resolve disputes between a taxpayer and the Internal Revenue Service when the IRS is no longer pursuing a levy.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"22"}},{"t":"case","label":"Corey v. Struve","cite":"149 P. 48","y":1915,"court":"Cal.","url":"https://www.courtlistener.com/c/P./149/48/","op":3,"by":{"1":"17","2":"17"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Federal Sugar Ref. Co. v. United States Sugar Equalization Bd.","cite":"268 F. 575","y":1920,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F./268/575/","by":{"1":"19","2":"17"}},{"t":"case","label":"Fischer v. United States","cite":"603 U.S. 480","y":2024,"id":"2023/23-5572","sc":1,"op":1,"sum":"The Court held that 18 U.S.C. § 1512(c), which prohibits obstruction of congressional inquiries and investigations, does not include acts unrelated to investigations and evidence.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Hateley v. SEC","cite":"8 F.3d 653","y":1993,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/8/653/","by":{"1":"34"}},{"t":"case","label":"Intel Corp. v. Advanced Micro Devices, Inc.","cite":"542 U.S. 241","y":2004,"id":"2003/02-572","sc":1,"sum":"In a 7-to-1 decision, the Court ruled that just because a foreign tribunal was unwilling to demand certain documents did not mean that it would be unwilling to accept them if provided to them by other means.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Kousisis v. United States","cite":"605 U.S. 114","y":2025,"id":"2024/23-909","sc":1,"sum":"A defendant who induces a victim to enter into a transaction under materially false pretenses may be convicted of federal fraud even if the defendant did not seek to cause the victim economic loss.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"20, 21, 29, 39"}},{"t":"case","label":"Merck & Co. v. Reynolds","cite":"559 U.S. 633","y":2010,"id":"2009/08-905","sc":1,"sum":"The Court held that a statute of limitations begins to run once a plaintiff actually discovers -- or a reasonably diligent plaintiff would have discovered -- the facts constituting the violation in the present case, whichever comes first.","sumSrc":"Oyez","by":{"1":"24, 26"}},{"t":"case","label":"Mertens v. Hewitt Assocs.","cite":"508 U.S. 248","y":1993,"id":"1992/91-1671","sc":1,"sum":"ERISA does not authorize suits for money damages against nonfiduciaries who knowingly participate in a fiduciary's breach of fiduciary duty. ERISA §502(a)(3) permits plan participants to bring civil actions to obtain \"appropriate equitable relief\" to redress violations of the statute or a plan. Assuming, arguendo,that this creates a cause of action against nonfiduciaries who knowingly assist in a fiduciary's breach …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"Olwell v. Nye & Nissen Co.","cite":"173 P.2d 652","y":1946,"court":"Wash.","url":"https://www.courtlistener.com/c/P.2d/173/652/","op":2,"by":{"1":"19","2":"5, 16"}},{"t":"case","label":"Petrella v. Metro-Goldwyn-Mayer, Inc.","cite":"572 U.S. 663","y":2014,"id":"2013/12-1315","sc":1,"sum":"The Court held that the doctrine of laches could not be used to prevent a copyright suit that seeks relief for damages that occurred within the three-year window allowed by the Copyright Act.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Randall v. Loftsgaarden","cite":"478 U.S. 647","y":1986,"id":"1985/85-519","sc":1,"sum":"The Court of Appeals erred in holding that §28(a) requires a rescissory recovery under § 12(2) or § 10(b) to be reduced by tax benefits received from a tax shelter investment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Raven Red Ash Coal Co. v. Ball","cite":"39 S.E.2d 231","y":1946,"court":"Va.","url":"https://www.courtlistener.com/c/S.E.2d/39/231/","op":3,"sum":"Upholding the award of a trespasser’s profits despite the absence of “damage to the realty”.","sumSrc":"brief:1","by":{"1":"19","2":"6, 17"}},{"t":"case","label":"Romag Fasteners, Inc. v. Fossil, Inc.","cite":"590 U.S. 212","y":2020,"id":"2019/18-1233","sc":1,"sum":"The Court held that under Section 35 of the Lanham Act, a plaintiff does not need to show willful infringement to receive an award of an infringer’s profits for a violation of Section 43(a).","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"SCA Hygiene Prods. Aktiebolag v. First Quality Baby Prods., LLC","cite":"580 U.S. 328","y":2017,"id":"2016/15-927","sc":1,"sum":"The Court determined that an unreasonable delay in litigation cannot bar claims for patent infringement that are brought within the six-year statutory period of limitations.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"SEC v. Bilzerian","cite":"29 F.3d 689","y":1994,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/29/689/","by":{"1":"24"}},{"t":"case","label":"SEC v. Blatt","cite":"583 F.2d 1325","y":1978,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/583/1325/","by":{"1":"24"}},{"t":"case","label":"SEC v. Blavin","cite":"760 F.2d 706","y":1985,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/760/706/","by":{"1":"25"}},{"t":"case","label":"SEC v. Commonwealth Chem. Sec., Inc.","cite":"574 F.2d 90","y":1978,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/574/90/","by":{"1":"25"}},{"t":"case","label":"SEC v. First City Fin. Corp.","cite":"890 F.2d 1215","y":1989,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/890/1215/","by":{"1":"25, 34, 35"}},{"t":"case","label":"SEC v. Gentile","cite":"939 F.3d 549","y":2019,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/939/549/","by":{"1":"7"}},{"t":"case","label":"SEC v. MacDonald","cite":"699 F.2d 47","y":1983,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/699/47/","by":{"1":"35"}},{"t":"case","label":"SEC v. Manor Nursing Ctrs., Inc.","cite":"458 F.2d 1082","y":1972,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/458/1082/","op":1,"by":{"1":"35"}},{"t":"case","label":"SEC v. Pirate Inv. LLC","cite":"580 F.3d 233","y":2009,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/580/233/","by":{"1":"23"}},{"t":"case","label":"SEC v. Platforms Wireless Int’l Corp.","cite":"617 F.3d 1072","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/617/1072/","by":{"1":"25"}},{"t":"case","label":"SEC v. Spartan Sec. Grp., Ltd.","cite":"164 F.4th 1231","y":2026,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/164/1231/","sum":"Explaining that, because “Congress omitted any investor-benefit language from sections [78u](d)(3)(A)(ii) and (d)(7),” the court “presume[d]” that those provisions “lack the investor-benefit requirement Congress provided for in section [78u](d)(5)”.","sumSrc":"brief:1","by":{"1":"35, 39"}},{"t":"case","label":"SEC v. Teo","cite":"746 F.3d 90","y":2014,"url":"https://www.courtlistener.com/c/F.3d/746/90/","by":{"1":"25"}},{"t":"case","label":"SEC v. Zwick","cite":"317 Fed. Appx. 34","y":2008,"court":"2d Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./317/34/","by":{"1":"14"}},{"t":"case","label":"Sekhar v. United States","cite":"570 U.S. 729","y":2013,"id":"2012/12-357","sc":1,"sum":"The Court held that attempting to compel a person to issue a recommendation does not constitute extortion under the Hobbs Act.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Spokeo, Inc. v. Robins","cite":"578 U.S. 330","y":2016,"id":"2015/13-1339","sc":1,"sum":"The Court held that lower courts need to consider the elements of Article III standing analysis separately in determining whether standing is sufficient for a federal court to hear the case.","sumSrc":"Oyez","by":{"1":"11, 19, 20, 29","2":"6"}},{"t":"case","label":"Stillwell v. Rankin","cite":"174 P. 186","y":1918,"court":"Mont.","url":"https://www.courtlistener.com/c/P./174/186/","by":{"1":"29"}},{"t":"case","label":"Taylor v. Meirick","cite":"712 F.2d 1112","y":1983,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/712/1112/","by":{"1":"18"}},{"t":"case","label":"Tellabs, Inc. v. Makor Issues & Rights, Ltd.","cite":"551 U.S. 308","y":2007,"id":"2006/06-484","sc":1,"sum":"The Court ruled by a vote of 8-1 that a securities fraud complaint must allege facts establishing an inference of guilty intent that is \"cogent and at least as compelling as any opposing inference of nonfraudulent intent.\" Justice Ruth Bader Ginsburg wrote that opinion for the Court, which held that the Seventh Circuit's more relaxed standard was not strong enough to comport with Congress's intent in PSLRA to limit securities fraud litigation. \"The strength of an inference cannot be decided in a vacuum.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"United States v. Carter","cite":"217 U.S. 286","y":1910,"id":"scdb/1909-135","sc":1,"op":1,"sum":"Where both the courts below have concurred upon material facts, the burden rests bn the appellant to satisfy this court that such conclusions are erroneous.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"30","2":"4, 15"}},{"t":"law","label":"Dodd-Frank Wall Street Reform and Consumer Protection Act, Pub. L. No. 111-203","url":"https://www.govinfo.gov/link/plaw/111/public/203","by":{"1":"23"}},{"t":"law","label":"Private Securities Litigation Reform Act, Pub. L. No. 104-67","url":"https://www.govinfo.gov/link/plaw/104/public/67","by":{"1":"22"}},{"t":"usc","label":"15 U.S.C. § 77a","url":"https://www.law.cornell.edu/uscode/text/15/77a","by":{"1":"7"}},{"t":"usc","label":"15 U.S.C. § 78a","url":"https://www.law.cornell.edu/uscode/text/15/78a","by":{"1":"2"}},{"t":"usc","label":"15 U.S.C. § 78c","url":"https://www.law.cornell.edu/uscode/text/15/78c","subs":["(a)(51)"],"by":{"1":"7"}},{"t":"usc","label":"15 U.S.C. § 78u-6","url":"https://www.law.cornell.edu/uscode/text/15/78u-6","subs":["(g)(3)(A)(i)"],"stext":{"head":"§78u–6. Securities whistleblower incentives and protection","paras":[[0,"(a) Definitions"],[0,"In this section the following definitions shall apply:"],[0,"(1) Covered judicial or administrative action"],[1,"The term \"covered judicial or administrative action\" means any judicial or administrative action brought by the Commission under the securities laws that results in monetary sanctions exceeding $1,000,000."],[0,"(2) Fund"],[1,"The term \"Fund\" means the Securities and Exchange Commission Investor Protection Fund."],[0,"(3) Original information"],[1,"The term \"original information\" means information that—"],[2,"(A) is derived from the independent knowledge or analysis of a whistleblower;"],[2,"(B) is not known to the Commission from any other source, unless the whistleblower is the original source of the information; and"],[2,"(C) is not exclusively derived from an allegation made in a judicial or administrative hearing, in a governmental report, hearing, audit, or investigation, or from the news media, unless the whistleblower is a source of the information."],[0,"(4) Monetary sanctions"],[1,"The term \"monetary sanctions\", when used with respect to any judicial or administrative action, means—"],[2,"(A) any monies, including penalties, disgorgement, and interest, ordered to be paid; and"],[2,"(B) any monies deposited into a disgorgement fund or other fund pursuant to section 308(b) of the Sarbanes-Oxley Act of 2002 (15 U.S.C. 7246(b)), as a result of such action or any settlement of such action."],[0,"(5) Related action"],[1,"The term \"related action\", when used with respect to any judicial or administrative action brought by the Commission under the securities laws, means any judicial or administrative action brought by an entity described in subclauses (I) through (IV) of subsection (h)(2)(D)(i) that is based upon the original information provided by a whistleblower pursuant to subsection (a) that led to the successful enforcement of the Commission action."],[0,"(6) Whistleblower"],[1,"The term \"whistleblower\" means any individual who provides, or 2 or more individuals acting jointly who provide, information relating to a violation of the securities laws to the Commission, in a manner established, by rule or regulation, by the Commission."],[0,"(b) Awards"],[0,"(1) In general"],[1,"In any covered judicial or administrative action, or related action, the Commission, under regulations prescribed by the Commission and subject to subsection (c), shall pay an award or awards to 1 or more whistleblowers who voluntarily provided original information to the Commission that led to the successful enforcement of the covered judicial or administrative action, or related action, in an aggregate amount equal to—"],[2,"(A) not less than 10 percent, in total, of what has been collected of the monetary sanctions imposed in the action or related actions; and"],[2,"(B) not more than 30 percent, in total, of what has been collected of the monetary sanctions imposed in the action or related actions."],[0,"(2) Payment of awards"],[1,"Any amount paid under paragraph (1) shall be paid from the Fund."],[0,"(c) Determination of amount of award; denial of award"],[0,"(1) Determination of amount of award"],[0,"(A) Discretion"],[2,"The determination of the amount of an award made under subsection (b) shall be in the discretion of the Commission."],[0,"(B) Criteria"],[2,"In determining the amount of an award made under subsection (b), the Commission—"],[3,"(i) shall take into consideration—"],[4,"(I) the significance of the information provided by the whistleblower to the success of the covered judicial or administrative action;"],[4,"(II) the degree of assistance provided by the whistleblower and any legal representative of the whistleblower in a covered judicial or administrative action;"],[4,"(III) the programmatic interest of the Commission in deterring violations of the securities laws by making awards to whistleblowers who provide information that lead to the successful enforcement of such laws; and"],[4,"(IV) such additional relevant factors as the Commission may establish by rule or regulation; and"],[3,"(ii) shall not take into consideration the balance of the Fund."],[0,"(2) Denial of award"],[1,"No award under subsection (b) shall be made—"],[2,"(A) to any whistleblower who is, or was at the time the whistleblower acquired the original information submitted to the Commission, a member, officer, or employee of—"],[3,"(i) an appropriate regulatory agency;"],[3,"(ii) the Department of Justice;"],[3,"(iii) a self-regulatory organization;"],[3,"(iv) the Public Company Accounting Oversight Board; or"],[3,"(v) a law enforcement organization;"],[2,"(B) to any whistleblower who is convicted of a criminal violation related to the judicial or administrative action for which the whistleblower otherwise could receive an award under this section;"],[2,"(C) to any whistleblower who gains the information through the performance of an audit of financial statements required under the securities laws and for whom such submission would be contrary to the requirements of section 78j–1 of this title; or"],[2,"(D) to any whistleblower who fails to submit information to the Commission in such form as the Commission may, by rule, require."],[0,"(d) Representation"],[0,"(1) Permitted representation"],[1,"Any whistleblower who makes a claim for an award under subsection (b) may be represented by counsel."],[0,"(2) Required representation"],[0,"(A) In general"],[2,"Any whistleblower who anonymously makes a claim for an award under subsection (b) shall be represented by counsel if the whistleblower anonymously submits the information upon which the claim is based."],[0,"(B) Disclosure of identity"],[2,"Prior to the payment of an award, a whistleblower shall disclose the identity of the whistleblower and provide such other information as the Commission may require, directly or through counsel for the whistleblower."],[0,"(e) No contract necessary"],[0,"No contract with the Commission is necessary for any whistleblower to receive an award under subsection (b), unless otherwise required by the Commission by rule or regulation."],[0,"(f) Appeals"],[0,"Any determination made under this section, including whether, to whom, or in what amount to make awards, shall be in the discretion of the Commission. Any such determination, except the determination of the amount of an award if the award was made in accordance with subsection (b), may be appealed to the appropriate court of appeals of the United States not more than 30 days after the determination is issued by the Commission. The court shall review the determination made by the Commission in accordance with section 706 of title 5."],[0,"(g) Investor Protection Fund"],[0,"(1) Fund established"],[1,"There is established in the Treasury of the United States a fund to be known as the \"Securities and Exchange Commission Investor Protection Fund\"."],[0,"(2) Use of Fund"],[1,"The Fund shall be available to the Commission, without further appropriation or fiscal year limitation, for—"],[2,"(A) paying awards to whistleblowers as provided in subsection (b); and"],[2,"(B) funding the activities of the Inspector General of the Commission under section 78d(i) of this title."],[0,"(3) Deposits and credits"],[0,"(A) In general"],[2,"There shall be deposited into or credited to the Fund an amount equal to—"],[3,"(i) any monetary sanction collected by the Commission in any judicial or administrative action brought by the Commission under the securities laws that is not added to a disgorgement fund or other fund under section 308 of the Sarbanes-Oxley Act of 2002 (15 U.S.C. 7246) or otherwise distributed to victims of a violation of the securities laws, or the rules and regulations thereunder, underlying such action, unless the balance of the Fund at the time the monetary sanction is collected exceeds $300,000,000;"],[3,"(ii) any monetary sanction added to a disgorgement fund or other fund under section 308 of the Sarbanes-Oxley Act of 2002 (15 U.S.C. 7246) that is not distributed to the victims for whom the Fund was established, unless the balance of the disgorgement fund at the time the determination is made not to distribute the monetary sanction to such victims exceeds $200,000,000; and"],[3,"(iii) all income from investments made under paragraph (4)."],[0,"(B) Additional amounts"],[2,"If the amounts deposited into or credited to the Fund under subparagraph (A) are not sufficient to satisfy an award made under subsection (b), there shall be deposited into or credited to the Fund an amount equal to the unsatisfied portion of the award from any monetary sanction collected by the Commission in the covered judicial or administrative action on which the award is based."],[0,"(4) Investments"],[0,"(A) Amounts in Fund may be invested"],[2,"The Commission may request the Secretary of the Treasury to invest the portion of the Fund that is not, in the discretion of the Commission, required to meet the current needs of the Fund."],[0,"(B) Eligible investments"],[2,"Investments shall be made by the Secretary of the Treasury in obligations of the United States or obligations that are guaranteed as to principal and interest by the United States, with maturities suitable to the needs of the Fund as determined by the Commission on the record."],[0,"(C) Interest and proceeds credited"],[2,"The interest on, and the proceeds from the sale or redemption of, any obligations held in the Fund shall be credited to the Fund."],[0,"(5) Reports to Congress"],[1,"Not later than October 30 of each fiscal year beginning after July 21, 2010, the Commission shall submit to the Committee on Banking, Housing, and Urban Affairs of the Senate, and the Committee on Financial Services of the House of Representatives a report on—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78u-6?type=usc&year=mostrecent&link-type=html"},"head":"§78u–6. Securities whistleblower incentives and protection","tname":"Commerce and Trade","by":{"1":"24, 39","2":"12"}},{"t":"case","label":"Edwards v. Lee’s Administrator","cite":"96 S.W.2d 1028","y":1936,"court":"Ky.","url":"https://www.courtlistener.com/c/S.W.2d/96/1028/","op":3,"by":{"2":"17"}},{"t":"case","label":"Harris Tr. & Sav. Bank v. Salomon Smith Barney, Inc.","cite":"530 U.S. 238","y":2000,"id":"1999/99-579","sc":1,"sum":"The Court held that Section 502(a)(3)'s authorization to a plan \"participant, beneficiary, or fiduciary\" to bring a civil action for \"appropriate equitable relief\" extends to a suit against a nonfiduciary \"party in interest\" to a prohibited transaction barred by section 406(a). \"We reject,\" wrote Justice Thomas that, \"absent a substantive provision of ERISA expressly imposing a duty upon a nonfiduciary party in interest, the nonfiduciary party may not be held liable under [section 502(a)(3)].\" Justice Thomas concluded that \"[section 502(a)(3)] itself imposes certain duties, and therefore that liability under that provision does not depend on whether ERISA's substantive provisions impose a specific duty on the party being sued.\".","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Keech v. Sandford","cite":"25 Eng. Rep. 223","y":1726,"court":"Ch.","url":"https://www.courtlistener.com/c/Eng.%20Rep./25/223/","by":{"2":"17"}},{"t":"case","label":"Sheldon v. Metro-Goldwyn Pictures Corp.","cite":"309 U.S. 390","y":1940,"id":"scdb/1939-111","sc":1,"ar":2,"sum":"1. That clause of § 25 (b) of the Copyright Act which authorizes recovery from an infringer, \"in lieu of actual damages and profits,\" of \"such 'damages as to the court shall appear to be just,\" is inapplicable where the only matter in question is the apportionment of profits established.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"7, 17"}}]};